import itertools

def has_monochromatic_triangle(n, edges):
    # edges is a list of 0s and 1s for (i, j) with 0 <= i < j < n
    # Map (i, j) to color
    adj = {}
    idx = 0
    for i in range(n):
        for j in range(i + 1, n):
            adj[(i, j)] = edges[idx]
            idx += 1

    for i, j, k in itertools.combinations(range(n), 3):
        # Check if (i, j), (j, k), (i, k) have the same color
        c1 = adj[(i, j)]
        c2 = adj[(j, k)]
        c3 = adj[(i, k)]
        if c1 == c2 == c3:
            return True
    return False

# Check for K_6
n = 6
num_edges = n * (n - 1) // 2
for edges in itertools.product([0, 1], repeat=num_edges):
    if not has_monochromatic_triangle(n, edges):
        print(f"Found coloring for K_{n}: {edges}")
        break
else:
    print(f"No coloring for K_{n}")
